def longest_palindromic_subsequence(string):
    # Initialize a 2D array to store the length of the longest palindromic subsequence for each substring of the given string
    dp = [[0] * len(string) for _ in range(len(string))]

    # Initialize the first row and column of the 2D array
    for i in range(len(string)):
        dp[i][i] = 1

    # Loop through the rest of the substrings and find the longest palindromic subsequence
    for i in range(len(string) - 1):
        for j in range(i + 1, len(string)):
            if string[i] == string[j]:
                dp[i][j] = 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    # Return the length of the longest palindromic subsequence
    return dp[0][len(string) - 1]

