def find_max_increasing_subsequence(prefix, i, k):
    """
    Find the maximum sum of an increasing subsequence from prefix until the ith index,
    including the kth element which is after the i, i.e., k > i.
    """
    return max(prefix[:i+1] + prefix[i+1:k+1])

def highest_power_of_2(n):
    if n == 0:
        return 0
    power = 0
    while n > 0:
        n >>= 1
        power += 1
    return power

def lucas_number(n):
    if n == 1:
        return 2
    elif n == 2:
        return 1
    else:
        return lucas_number(n-1) + lucas_number(n-2)

