def next_bigger(n):
    digits = [int(d) for d in str(n)]
    digits.sort(reverse=True)
    for i in range(len(digits) - 1):
        if digits[i] > digits[i + 1]:
            digits[i + 1] = digits[i]
            digits[i] = digits[i + 1]
            break
    else:
        digits.reverse()
    return int("".join(map(str, digits)))

