def longest_common_subsequence(str1, str2, str3):
    # Find the length of the shortest string
    n = min(len(str1), len(str2), len(str3))

    # Create a 2D array to store the length of the LCS for each index
    lcs = [[0 for i in range(n+1)] for j in range(n+1)]

    # Loop through each index of the shortest string
    for i in range(1, n+1):
        for j in range(1, n+1):
            # If the current character of all strings is the same, the LCS length is 1 + the LCS length of the previous index
            if str1[i-1] == str2[j-1] == str3[j-1]:
                lcs[i][j] = 1 + lcs[i-1][j-1]
            # If the current character of all strings is not the same, the LCS length is the maximum of the LCS lengths of the previous indices
            else:
                lcs[i][j] = max(lcs[i-1][j], lcs[i][j-1], lcs[i-1][j-1])

    # Return the LCS length of the last index
    return lcs[n][n]

