def is_min_heap(arr):
    """
    Returns True if the given array represents a min heap, False otherwise.
    """
    if len(arr) == 0:
        return False
    for i in range(len(arr)):
        if i * 2 + 1 >= len(arr):
            break
        if arr[i] > arr[i * 2 + 1]:
            return False
        if i * 2 + 2 < len(arr) and arr[i] > arr[i * 2 + 2]:
            return False
    return True

def jacobsthal(n):
    if n == 0:
        return 0
    if n == 1:
        return 1
    return jacobsthal(n-1) + jacobsthal(n-2)

