def rgb_to_hsv(rgb):
    r, g, b = rgb
    h, s, v = 0, 0, 0

    # Calculate h
    if r == g and g == b:
        h = 0
    elif r > g and g == b:
        h = 360 * (r - g) / (r + g)
    elif r > g and g > b:
        h = 360 * (r - g) / (r - b)
    elif r == g and g > b:
        h = 360 * (r - g) / (r - b)
    elif r < g and g == b:
        h = 360 * (r - g) / (r + g)
    elif r < g and g > b:
        h = 360 * (r - g) / (r - b)
    elif r == g and g < b:
        h = 360 * (r - g) / (r - b)

    # Calculate s
    if r == g and g == b:
        s = 0
    else:
        s = 1 - min(r, g, b) / max(r, g, b)

    # Calculate v
    v = max(r, g, b)

    return (h, s, v)

